class Solution:
    def containVirus(self, isInfected):
        m, n = len(isInfected), len(isInfected[0])
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        walls = 0
        while True:
            seen = [[False]*n for _ in range(m)]
            regions, threats, wallcnt = [], [], []
            for i in range(m):
                for j in range(n):
                    if isInfected[i][j] == 1 and not seen[i][j]:
                        stack = [(i,j)]; seen[i][j] = True
                        cells, threat, wc = [], set(), 0
                        while stack:
                            x, y = stack.pop(); cells.append((x,y))
                            for dx, dy in dirs:
                                nx, ny = x+dx, y+dy
                                if 0 <= nx < m and 0 <= ny < n:
                                    if isInfected[nx][ny] == 0:
                                        threat.add((nx,ny)); wc += 1
                                    elif isInfected[nx][ny] == 1 and not seen[nx][ny]:
                                        seen[nx][ny] = True; stack.append((nx,ny))
                        regions.append(cells); threats.append(threat); wallcnt.append(wc)
            if not regions or not any(threats):
                return walls
            idx = max(range(len(regions)), key=lambda k: len(threats[k]))
            walls += wallcnt[idx]
            for x, y in regions[idx]:
                isInfected[x][y] = -1
            for k, th in enumerate(threats):
                if k != idx:
                    for x, y in th:
                        isInfected[x][y] = 1

