class Solution {
public:
    int containVirus(vector<vector<int>>& g) {
        int m = g.size(), n = g[0].size(), walls = 0;
        int dx[] = {1,-1,0,0}, dy[] = {0,0,1,-1};
        while (true) {
            vector<vector<bool>> seen(m, vector<bool>(n,false));
            vector<vector<pair<int,int>>> regs;
            vector<set<pair<int,int>>> thr;
            vector<int> wc;
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (g[i][j] != 1 || seen[i][j]) continue;
                vector<pair<int,int>> st = {{i,j}}, cells;
                set<pair<int,int>> t; int w = 0;
                seen[i][j] = true;
                while (!st.empty()) {
                    auto [x,y] = st.back(); st.pop_back(); cells.push_back({x,y});
                    for (int d = 0; d < 4; d++) {
                        int nx = x+dx[d], ny = y+dy[d];
                        if (nx<0||ny<0||nx>=m||ny>=n) continue;
                        if (g[nx][ny]==0) { t.insert({nx,ny}); w++; }
                        else if (g[nx][ny]==1 && !seen[nx][ny]) { seen[nx][ny]=true; st.push_back({nx,ny}); }
                    }
                }
                regs.push_back(cells); thr.push_back(t); wc.push_back(w);
            }
            if (regs.empty()) return walls;
            int best = -1, bi = -1;
            for (int k = 0; k < (int)regs.size(); k++)
                if ((int)thr[k].size() > best) { best = thr[k].size(); bi = k; }
            if (best == 0) return walls;
            walls += wc[bi];
            for (auto& [x,y] : regs[bi]) g[x][y] = -1;
            for (int k = 0; k < (int)regs.size(); k++)
                if (k != bi)
                    for (auto& [x,y] : thr[k]) g[x][y] = 1;
        }
    }
};

