class Solution {
    public int containVirus(int[][] g) {
        int m = g.length, n = g[0].length, walls = 0;
        int[] dx = {1,-1,0,0}, dy = {0,0,1,-1};
        while (true) {
            boolean[][] seen = new boolean[m][n];
            List<List<int[]>> regs = new ArrayList<>();
            List<Set<Long>> thr = new ArrayList<>();
            List<Integer> wc = new ArrayList<>();
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (g[i][j] != 1 || seen[i][j]) continue;
                Deque<int[]> st = new ArrayDeque<>();
                List<int[]> cells = new ArrayList<>();
                Set<Long> t = new HashSet<>(); int w = 0;
                seen[i][j] = true; st.push(new int[]{i,j});
                while (!st.isEmpty()) {
                    int[] c = st.pop(); cells.add(c);
                    for (int d = 0; d < 4; d++) {
                        int nx = c[0]+dx[d], ny = c[1]+dy[d];
                        if (nx<0||ny<0||nx>=m||ny>=n) continue;
                        if (g[nx][ny]==0) { t.add(((long)nx<<32)|ny); w++; }
                        else if (g[nx][ny]==1 && !seen[nx][ny]) { seen[nx][ny]=true; st.push(new int[]{nx,ny}); }
                    }
                }
                regs.add(cells); thr.add(t); wc.add(w);
            }
            if (regs.isEmpty()) return walls;
            int best = -1, bi = -1;
            for (int k = 0; k < regs.size(); k++)
                if (thr.get(k).size() > best) { best = thr.get(k).size(); bi = k; }
            if (best == 0) return walls;
            walls += wc.get(bi);
            for (int[] c : regs.get(bi)) g[c[0]][c[1]] = -1;
            for (int k = 0; k < regs.size(); k++)
                if (k != bi)
                    for (long v : thr.get(k)) g[(int)(v>>>32)][(int)(v & 0xffffffffL)] = 1;
        }
    }
}

