class Solution:
    def containVirus(self, isInfected):
        m, n = len(isInfected), len(isInfected[0])
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        walls = 0
        while True:
            rid = [[-1]*n for _ in range(m)]
            regions = {}
            nxt = 0
            for i in range(m):
                for j in range(n):
                    if isInfected[i][j] == 1 and rid[i][j] == -1:
                        stack = [(i,j)]; rid[i][j] = nxt; regions[nxt] = []
                        while stack:
                            x, y = stack.pop(); regions[nxt].append((x,y))
                            for dx, dy in dirs:
                                nx, ny = x+dx, y+dy
                                if 0 <= nx < m and 0 <= ny < n and isInfected[nx][ny] == 1 and rid[nx][ny] == -1:
                                    rid[nx][ny] = nxt; stack.append((nx,ny))
                        nxt += 1
            threat = {}   # cell -> list of region ids bordering it
            for i in range(m):
                for j in range(n):
                    if isInfected[i][j] == 0:
                        ids = [rid[i+dx][j+dy] for dx, dy in dirs
                               if 0 <= i+dx < m and 0 <= j+dy < n and rid[i+dx][j+dy] >= 0]
                        if ids:
                            threat[(i,j)] = ids
            if not threat:
                return walls
            size = {}
            cost = {}
            for cell, ids in threat.items():
                for r in set(ids):
                    size[r] = size.get(r, 0) + 1
                    cost[r] = cost.get(r, 0) + ids.count(r)
            best = max(size, key=lambda r: size[r])
            walls += cost[best]
            for x, y in regions[best]:
                isInfected[x][y] = -1
            for (x, y), ids in threat.items():
                if best not in ids:
                    isInfected[x][y] = 1

