class Solution {
public:
    int containVirus(vector<vector<int>>& g) {
        int m = g.size(), n = g[0].size(), walls = 0;
        int dx[] = {1,-1,0,0}, dy[] = {0,0,1,-1};
        while (true) {
            vector<vector<int>> rid(m, vector<int>(n,-1));
            map<int,vector<pair<int,int>>> regions;
            int nxt = 0;
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (g[i][j] != 1 || rid[i][j] != -1) continue;
                vector<pair<int,int>> st = {{i,j}}; rid[i][j] = nxt;
                while (!st.empty()) {
                    auto [x,y] = st.back(); st.pop_back(); regions[nxt].push_back({x,y});
                    for (int d = 0; d < 4; d++) {
                        int nx = x+dx[d], ny = y+dy[d];
                        if (nx>=0&&ny>=0&&nx<m&&ny<n&&g[nx][ny]==1&&rid[nx][ny]==-1){rid[nx][ny]=nxt;st.push_back({nx,ny});}
                    }
                }
                nxt++;
            }
            map<pair<int,int>,vector<int>> threat;
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (g[i][j] != 0) continue;
                vector<int> ids;
                for (int d = 0; d < 4; d++) {
                    int nx=i+dx[d], ny=j+dy[d];
                    if (nx>=0&&ny>=0&&nx<m&&ny<n&&rid[nx][ny]>=0) ids.push_back(rid[nx][ny]);
                }
                if (!ids.empty()) threat[{i,j}] = ids;
            }
            if (threat.empty()) return walls;
            map<int,int> sz, cost;
            for (auto& [cell, ids] : threat) {
                set<int> u(ids.begin(), ids.end());
                for (int r : u) { sz[r]++; cost[r] += count(ids.begin(), ids.end(), r); }
            }
            int best = 0, bs = -1;
            for (auto& [r, s] : sz) if (s > bs) { bs = s; best = r; }
            walls += cost[best];
            for (auto& [x,y] : regions[best]) g[x][y] = -1;
            for (auto& [cell, ids] : threat)
                if (find(ids.begin(), ids.end(), best) == ids.end())
                    g[cell.first][cell.second] = 1;
        }
    }
};

