class Solution {
    public int containVirus(int[][] g) {
        int m = g.length, n = g[0].length, walls = 0;
        int[] dx = {1,-1,0,0}, dy = {0,0,1,-1};
        while (true) {
            int[][] rid = new int[m][n];
            for (int[] row : rid) java.util.Arrays.fill(row, -1);
            Map<Integer, List<int[]>> regions = new HashMap<>();
            int nxt = 0;
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (g[i][j] != 1 || rid[i][j] != -1) continue;
                Deque<int[]> st = new ArrayDeque<>();
                st.push(new int[]{i,j}); rid[i][j] = nxt;
                regions.put(nxt, new ArrayList<>());
                while (!st.isEmpty()) {
                    int[] c = st.pop(); regions.get(nxt).add(c);
                    for (int d = 0; d < 4; d++) {
                        int nx=c[0]+dx[d], ny=c[1]+dy[d];
                        if (nx>=0&&ny>=0&&nx<m&&ny<n&&g[nx][ny]==1&&rid[nx][ny]==-1){rid[nx][ny]=nxt;st.push(new int[]{nx,ny});}
                    }
                }
                nxt++;
            }
            Map<Long, List<Integer>> threat = new HashMap<>();
            for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
                if (g[i][j] != 0) continue;
                List<Integer> ids = new ArrayList<>();
                for (int d = 0; d < 4; d++) {
                    int nx=i+dx[d], ny=j+dy[d];
                    if (nx>=0&&ny>=0&&nx<m&&ny<n&&rid[nx][ny]>=0) ids.add(rid[nx][ny]);
                }
                if (!ids.isEmpty()) threat.put(((long)i<<32)|j, ids);
            }
            if (threat.isEmpty()) return walls;
            Map<Integer,Integer> sz = new HashMap<>(), cost = new HashMap<>();
            for (List<Integer> ids : threat.values()) {
                Set<Integer> u = new HashSet<>(ids);
                for (int r : u) { sz.merge(r,1,Integer::sum); cost.merge(r, java.util.Collections.frequency(ids,r), Integer::sum); }
            }
            int best = -1, bs = -1;
            for (var e : sz.entrySet()) if (e.getValue() > bs) { bs = e.getValue(); best = e.getKey(); }
            walls += cost.get(best);
            for (int[] c : regions.get(best)) g[c[0]][c[1]] = -1;
            for (var e : threat.entrySet())
                if (!e.getValue().contains(best))
                    g[(int)(e.getKey()>>>32)][(int)(e.getKey() & 0xffffffffL)] = 1;
        }
    }
}

