            if (isInfected[i][j] !== 1 || rid[i][j] !== -1) continue;
            const st = [[i,j]]; rid[i][j] = nxt; regions[nxt] = [];
            while (st.length) {
                const [x,y] = st.pop(); regions[nxt].push([x,y]);
                for (const [dx,dy] of dirs) {
                    const nx = x+dx, ny = y+dy;
                    if (nx>=0&&ny>=0&&nx<m&&ny<n&&isInfected[nx][ny]===1&&rid[nx][ny]===-1){rid[nx][ny]=nxt;st.push([nx,ny]);}
                }
            }
            nxt++;
        }
        const threat = new Map();
        for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
            if (isInfected[i][j] !== 0) continue;
            const ids = [];
            for (const [dx,dy] of dirs) {
                const nx=i+dx, ny=j+dy;
                if (nx>=0&&ny>=0&&nx<m&&ny<n&&rid[nx][ny]>=0) ids.push(rid[nx][ny]);
            }
